import { launchAttempt, reserveAttempt, } from './standalone-attempt.js';
const engineOwners = realmSlot('e2e.standalone.engines.v1');
function owners() {
    let set = engineOwners.get(globalThis);
    if (set === undefined) {
        set = new WeakSet();
        engineOwners.set(globalThis, set);
    }
    return set;
}
